  const match = /^(https?):\/\/([a-z0-9.-]+)(\/[^\s#]*)?(?:#[^\s]*)?$/i.exec(url);
  if (!match || !match[2].includes('.') || /(?:^|\.)localhost$/i.test(match[2]) || /^[\d.]+$/.test(match[2])) throw new Error('input_url_invalid');
  url = match[1].toLowerCase()+'://'+match[2].toLowerCase()+(match[3] || '/');
  const maxChars = input.maxChars ?? 30000;
  if (!Number.isInteger(maxChars) || maxChars < 1000 || maxChars > 50000) throw new Error('input_max_chars_invalid');
